  for (const k in REWARD_DEFAULTS) out[k] = k === "artist" ? REWARD_DEFAULTS.artist.map((d, i) => n(Array.isArray(o.artist) ? o.artist[i] : undefined, d)) : n(o[k], REWARD_DEFAULTS[k]);
