    this.cache = {}; this.overrides = {}; this.pieceImgs = {}; this.itemImgs = {}; this.packToken = 0;
    this.player = { sheet: "player", x: 0, y: 0, dir: "up", moving: false, prog: 0, step: false, bumpT: 0, turnT: 0, walking: false };
