    const g = !id ? { swap: {} } : /^look:/.test(id) ? { swap: Object.fromEntries(id.slice(5).split(",").map(pr => pr.split("-").map(c => "#" + c))) } : BLUU_GEAR.find(b => b.id === id); // your look, or a Bluu colorway
    if (!w || !h || !g) return src;
