    if (!aw || !ah) return;
    const read = im => { const c = document.createElement("canvas"); c.width = aw; c.height = ah; const x = c.getContext("2d", { willReadFrequently: true }); x.drawImage(im, 0, 0); return x.getImageData(0, 0, aw, ah).data; };
