    this.boardBusy = true; this.boardAt = now;
    this.rpc("get_leaderboard").then(b => { this.board = b && Array.isArray(b.top) ? b : null; this.boardErr = !this.board; })
      .catch(() => { this.boardErr = true; }).finally(() => { this.boardBusy = false; });
