    if (e.name) return "EMPLOYEE OF THE MONTH: " + e.name;
    if (a && a.name) return (a.sofar ? "LEADING " + (a.month || "THIS MONTH") : "EMPLOYEE OF THE MONTH") + ": " + a.name + " - " + a.points + " PTS";
